assert len(DATA) == 10
TARGETS = ["A", "B", "C", "D", "B", "C", "D", "A", "B", "C"]
for i, (prompt, options, answer, explanation, strategy, steps) in enumerate(DATA, 1):
    target = TARGETS[i - 1]
    if target != answer:
        oi, ti = ord(answer) - 65, ord(target) - 65
        correct = options[oi]
        rest = [v for j, v in enumerate(options) if j != oi]
        options = rest[:ti] + [correct] + rest[ti:]
        explanation = explanation.replace(f"{answer} ", f"{target} ")
        steps = [s.replace(f"{answer} ", f"{target} ") for s in steps]
        answer = target
    item = {"id": f"question-chinese-content-cb-iv-1-{i}", "subject": "chinese", "type": "single-choice", "prompt": prompt, "options": [{"id": chr(65+j), "text": t} for j, t in enumerate(options)], "knowledgeIds": ["kg-chinese-content-cb-iv-1"], "difficulty": "medium", "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "公立學校公開國文段考與課程資料；只研究親屬、倫理、儀式、制度角色與史料範圍。", "authoringNote": "依官方語文領域課綱、單元 KG 與三個公立學校公開來源，獨立改寫親屬倫理與制度文化文本題；未複製原文、選項、篇章、圖片或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-13", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}
